export type AccountStatus = 'ACTIVE' | 'PENDING_AUDIT' | 'RESTRICTED' | 'MAINTENANCE' | 'SYNCING';

export type CurrencyCode = 'USD' | 'EUR' | 'GBP' | 'SGD' | 'JPY' | 'CHF' | 'AUD' | 'CAD';

export interface CitiAccount {
  id: string;
  name: string;
  balance: number;
  currency: CurrencyCode;
  status: AccountStatus;
  routingNumber: string;
  swiftBic: string;
  institutionType: 'CORRESPONDENT' | 'CENTRAL_LIQUIDITY' | 'INVESTMENT_SWEEP' | 'RETAIL_TREASURY';
  lastReconciled: string;
  riskScore: number; // 0 - 100
  yieldRate: number; // APY percentage
}

export interface TreasuryTransaction {
  id: string;
  accountId: string;
  referenceId: string;
  counterparty: string;
  amount: number;
  currency: CurrencyCode;
  type: 'WIRE' | 'ACH' | 'SWIFT_MT103' | 'SWIFT_MT202' | 'INTERNAL_TRANSFER' | 'FX_SETTLEMENT';
  status: 'SETTLED' | 'PENDING_COMPLIANCE' | 'PROCESSING' | 'REJECTED' | 'QUEUED';
  timestamp: string;
  initiator: string;
  complianceChecked: boolean;
  sanctionScreened: boolean;
}

export interface LiquidityForecastMetric {
  horizon: '24H' | '7D' | '30D' | '90D' | '1Y';
  projectedInflow: number;
  projectedOutflow: number;
  netPosition: number;
  liquidityBufferRatio: number;
  stressTestScenarioStatus: 'OPTIMAL' | 'STABLE' | 'WARNING' | 'CRITICAL';
}

export interface SystemAuditLog {
  id: string;
  severity: 'INFO' | 'WARNING' | 'CRITICAL' | 'SECURITY';
  message: string;
  timestamp: string;
  sourceModule: string;
}

export interface DashboardState {
  accounts: CitiAccount[];
  transactions: TreasuryTransaction[];
  forecast: Record<string, LiquidityForecastMetric>;
  auditLogs: SystemAuditLog[];
  selectedCurrencyFilter: CurrencyCode | 'ALL';
  searchQuery: string;
  isSyncing: boolean;
  isAutomatedSweepEnabled: boolean;
  activeTab: 'OVERVIEW' | 'ACCOUNTS' | 'TRANSACTIONS' | 'FORECAST' | 'COMPLIANCE' | 'API_CONFIG';
  selectedAccountDetail: CitiAccount | null;
  notificationMessage: { type: 'success' | 'error' | 'info'; text: string } | null;
  riskThresholdLimit: number;
}

